#include "../../04-图论/一般图带权匹配.cpp"
int main(){mt19937 r(101);for(int t=0;t<250;t++){int n=1+r()%10;vector<vector<long long>> w(n,vector<long long>(n));Blossom b(n);for(int i=0;i<n;i++)for(int j=0;j<i;j++){long long x=int(r()%61)-20;w[i][j]=w[j][i]=max(0LL,x);b.add_edge(i+1,j+1,x);}vector<long long> dp(1<<n,-1);auto dfs=[&](auto&&dfs,int mask)->long long{if(!mask)return 0;if(dp[mask]>=0)return dp[mask];int i=__builtin_ctz((unsigned)mask),rest=mask^(1<<i);long long ans=dfs(dfs,rest);for(int j=i+1;j<n;j++)if(rest>>j&1)ans=max(ans,w[i][j]+dfs(dfs,rest^(1<<j)));return dp[mask]=ans;};auto [ans,cnt]=b.solve();assert(ans==dfs(dfs,(1<<n)-1));long long sum=0;int c=0;for(int i=1;i<=n;i++)if(b.match[i]){int j=b.match[i];assert(j!=i&&b.match[j]==i&&w[i-1][j-1]>0);if(i<j)sum+=w[i-1][j-1],c++;}assert(sum==ans&&c==cnt);}}
